/**
 * The response field names the client reads (`src/api.ts`) against the contract the backend
 * publishes (`docs/openapi.json`, regenerated by `npm run openapi`). P21 B2 / A-15, ADR-0082.
 *
 * Each row maps a DTO in api.ts to the response schema it is transcribed from. Every field the DTO
 * declares must exist in that schema: a field renamed or dropped on either side fails here, before
 * a screen silently shows `undefined`. Fields the server sends and the client ignores are fine.
 * (A generated client, openapi-typescript, is OQ-29 and waits for the owner.)
 */
import { readFileSync } from "node:fs";
import path from "node:path";

import ts from "typescript";
import { describe, expect, it } from "vitest";

const here = path.dirname(new URL(import.meta.url).pathname);
const API_TS = readFileSync(path.join(here, "api.ts"), "utf8");
const OPENAPI = JSON.parse(readFileSync(path.join(here, "..", "..", "docs", "openapi.json"), "utf8")) as OpenApi;

interface Schema {
  $ref?: string;
  properties?: Record<string, Schema>;
  items?: Schema;
  allOf?: Schema[];
  anyOf?: Schema[];
  oneOf?: Schema[];
}
interface OpenApi {
  paths: Record<string, Record<string, { responses: Record<string, { content?: Record<string, { schema: Schema }> }> }>>;
  components?: { schemas?: Record<string, Schema> };
}

/** DTO → where its fields come from: method, path, status, and a pointer into the body (`[]` = array items). */
export const CONTRACT: Array<{ dto: string; method: string; path: string; status: string; at?: string[] }> = [
  { dto: "User", method: "post", path: "/auth/login", status: "200", at: ["user"] },
  { dto: "ModelDto", method: "get", path: "/models", status: "200", at: ["models", "[]"] },
  { dto: "ChatDto", method: "get", path: "/chats/{id}", status: "200" },
  { dto: "MessageDto", method: "get", path: "/chats/{id}", status: "200", at: ["messages", "[]"] },
  { dto: "ProjectDto", method: "post", path: "/projects", status: "201" },
  { dto: "ProjectFileDto", method: "get", path: "/projects/{id}/files/{fileId}", status: "200" },
  { dto: "SavedSourceDto", method: "get", path: "/projects/{id}/sources", status: "200", at: ["items", "[]"] },
  { dto: "ArtifactDto", method: "patch", path: "/artifacts/{id}", status: "200" },
  { dto: "ArtifactContentDto", method: "get", path: "/artifacts/{id}", status: "200" },
  { dto: "ArtifactVersionDto", method: "get", path: "/artifacts/{id}/versions", status: "200", at: ["items", "[]"] },
  { dto: "AttachmentDto", method: "get", path: "/files/{id}", status: "200" },
  { dto: "DirectUploadDto", method: "post", path: "/files/uploads", status: "201" },
  { dto: "PreferencesDto", method: "get", path: "/preferences", status: "200" },
  { dto: "UsageSummaryDto", method: "get", path: "/usage", status: "200" },
  { dto: "LimitsDto", method: "get", path: "/usage/limits", status: "200" },
  { dto: "MemoryItemDto", method: "post", path: "/memory", status: "200" },
  { dto: "MemoryListDto", method: "get", path: "/memory", status: "200" },
  { dto: "StyleDto", method: "get", path: "/styles/{id}", status: "200" },
  { dto: "StylesListDto", method: "get", path: "/styles", status: "200" },
  { dto: "MemoryExportDto", method: "get", path: "/memory/export", status: "200" },
  { dto: "ShareLinkDto", method: "post", path: "/chats/{id}/share", status: "200" },
];

function deref(schema: Schema, api: OpenApi): Schema {
  if (!schema.$ref) return schema;
  const name = schema.$ref.split("/").pop()!;
  return api.components?.schemas?.[name] ?? {};
}

/** Every variant a schema may take: itself and its allOf / anyOf / oneOf branches, dereferenced. */
function variants(schema: Schema, api: OpenApi): Schema[] {
  const s = deref(schema, api);
  return [s, ...[...(s.allOf ?? []), ...(s.anyOf ?? []), ...(s.oneOf ?? [])].flatMap((x) => variants(x, api))];
}

export function propertyNames(schema: Schema, api: OpenApi): Set<string> {
  return new Set(variants(schema, api).flatMap((v) => Object.keys(v.properties ?? {})));
}

export function responseSchema(api: OpenApi, row: (typeof CONTRACT)[number]): Schema | undefined {
  let s: Schema | undefined = api.paths[row.path]?.[row.method]?.responses[row.status]?.content?.["application/json"]?.schema;
  for (const step of row.at ?? []) {
    if (!s) return undefined;
    const vs = variants(s, api);
    s = step === "[]" ? vs.map((v) => v.items).find(Boolean) : vs.map((v) => v.properties?.[step]).find(Boolean);
  }
  return s;
}

/** The property names an interface or type alias in `source` declares (intersections followed). */
export function dtoFields(source: string, name: string): Set<string> {
  const file = ts.createSourceFile("api.ts", source, ts.ScriptTarget.Latest, true, ts.ScriptKind.TS);
  const out = new Set<string>();
  const fromMembers = (members: ts.NodeArray<ts.TypeElement>): void => {
    for (const m of members) if (ts.isPropertySignature(m) && m.name && (ts.isIdentifier(m.name) || ts.isStringLiteral(m.name))) out.add(m.name.text);
  };
  const fromType = (type: ts.TypeNode): void => {
    if (ts.isTypeLiteralNode(type)) fromMembers(type.members);
    else if (ts.isIntersectionTypeNode(type)) type.types.forEach(fromType);
    else if (ts.isTypeReferenceNode(type) && ts.isIdentifier(type.typeName)) for (const f of dtoFields(source, type.typeName.text)) out.add(f);
  };
  let found = false;
  file.forEachChild((node) => {
    if (ts.isInterfaceDeclaration(node) && node.name.text === name) {
      found = true;
      fromMembers(node.members);
    } else if (ts.isTypeAliasDeclaration(node) && node.name.text === name) {
      found = true;
      fromType(node.type);
    }
  });
  if (!found) throw new Error(`api.ts has no type ${name}`);
  return out;
}

/** The DTO fields the contract does not have, per row. */
export function divergences(source: string, api: OpenApi): string[] {
  const out: string[] = [];
  for (const row of CONTRACT) {
    const schema = responseSchema(api, row);
    if (!schema) {
      out.push(`${row.dto}: no ${row.method.toUpperCase()} ${row.path} ${row.status} ${(row.at ?? []).join(".")} in openapi.json`);
      continue;
    }
    const server = propertyNames(schema, api);
    for (const field of dtoFields(source, row.dto)) {
      if (!server.has(field)) out.push(`${row.dto}.${field}: not in ${row.method.toUpperCase()} ${row.path} ${row.status}`);
    }
  }
  return out;
}

describe("api.ts ↔ docs/openapi.json (P21 B2)", () => {
  it("every response field the client declares is in the published contract", () => {
    expect(divergences(API_TS, OPENAPI)).toEqual([]);
  });

  it("reads real fields on both sides (the check is not vacuous)", () => {
    expect(dtoFields(API_TS, "ChatDto").has("title")).toBe(true);
    expect(dtoFields(API_TS, "ArtifactContentDto").has("content")).toBe(true);
    expect(dtoFields(API_TS, "ArtifactContentDto").has("currentVersion")).toBe(true);
    for (const row of CONTRACT) expect(responseSchema(OPENAPI, row), row.dto).toBeDefined();
  });

  it("fails on a renamed field on either side", () => {
    const renamedClient = API_TS.replace(/(export interface ChatDto \{[\s\S]*?)\btitle: string;/, "$1titel: string;");
    expect(renamedClient).not.toBe(API_TS);
    expect(divergences(renamedClient, OPENAPI)).toContain("ChatDto.titel: not in GET /chats/{id} 200");

    const renamedServer = JSON.parse(JSON.stringify(OPENAPI)) as OpenApi;
    const chat = renamedServer.paths["/chats/{id}"]!.get!.responses["200"]!.content!["application/json"]!.schema;
    const holder = variants(chat, renamedServer).find((v) => v.properties?.["updatedAt"])!;
    holder.properties!["updated_at"] = holder.properties!["updatedAt"]!;
    delete holder.properties!["updatedAt"];
    expect(divergences(API_TS, renamedServer)).toContain("ChatDto.updatedAt: not in GET /chats/{id} 200");
  });
});
